416	          const content = await readFile(path.join(migrationDir, migrationKey), "utf8");
417	          const checksum = createHash("sha256").update(content).digest("hex");
418	          const existingRows = await tx
419	            .select()
420	            .from(pluginMigrations)
421	            .where(and(eq(pluginMigrations.pluginId, pluginId), eq(pluginMigrations.migrationKey, migrationKey)))
422	            .limit(1);
423	          const existing = existingRows[0] as PluginMigrationRecord | undefined;
424	          if (existing?.status === "applied") {
425	            if (existing.checksum !== checksum) {
426	              throw new Error(`Plugin migration checksum mismatch for ${migrationKey}`);
